  1198	/// Only the local route runs a comparison pool; every wire carrier still
  1199	/// diffs sequentially. Accepting `--checkers N` there and running unchanged
  1200	/// would silently invalidate whatever measurement the pin was set up to take
  1201	/// — and the flag exists ONLY to take measurements, so a pin that quietly
  1202	/// does nothing defeats its single purpose. Refusing is the honest failure.
  1203	pub(crate) fn reject_unsupported_checker_pin(
