   332	impl Read for ChunkReader {
   333	    fn read(&mut self, out: &mut [u8]) -> io::Result<usize> {
   334	        while self.pos == self.chunk.len() {
   335	            match self.rx.blocking_recv() {
   336	                Some(Ok(chunk)) => {
   337	                    self.chunk = chunk;
   338	                    self.pos = 0;
   339	                }
   340	                Some(Err(error)) => return Err(error),
   341	                None => return Ok(0),
   342	            }
   343	        }
   344	        let n = out.len().min(self.chunk.len() - self.pos);
   345	        out[..n].copy_from_slice(&self.chunk[self.pos..self.pos + n]);
   346	        self.pos += n;
   347	        Ok(n)
   348	    }
   349	}
