 /// `blit <args>` with its main thread held to the budget.
 fn budgeted_blit(config_dir: Option<&Path>, args: &[String]) -> Command {
     #[cfg(unix)]
     let mut cmd = {
         let mut cmd = Command::new("/bin/sh");
         cmd.arg("-c")
             .arg(format!("ulimit -S -s {BUDGET_KIB} && exec \"$0\" \"$@\""))
             .arg(cli_bin());
