+    cmd.arg("--config-dir").arg(dir);
     cmd.args(args);
     cmd
 }

 fn run(config_dir: Option<&Path>, args: &[String]) -> Output {
     run_with_timeout(budgeted_blit(config_dir, args), Duration::from_secs(120))
 }

